public void update(double deltaSeconds) {
    if (!running) return;
    if (deltaSeconds < 0) {
        throw new IllegalArgumentException("Delta seconds cannot be negative.");
    }
    accumulatedSeconds += deltaSeconds;
    while (running && accumulatedSeconds >= 1) {
        accumulatedSeconds -= 1;
        secondsCount--;
        if (secondsCount <= 0) {
            secondsCount = 0;
            running = false;
            onTimeUp.run();
        }
    }
}

